-- Read-only profiling queries for the map-qa snapshot. Run from the data folder via run_sql.py.
SELECT typeof(geometry) AS geometry_type_without_spatial FROM read_parquet('osm_roads.parquet') LIMIT 1;
LOAD spatial;
-- 1 schemas
DESCRIBE SELECT * FROM read_parquet('osm_roads.parquet');
DESCRIBE SELECT * FROM read_parquet('overture_segments.parquet');
DESCRIBE SELECT * FROM read_csv('photos.csv');
DESCRIBE SELECT * FROM read_csv('photo_road_links.csv');
DESCRIBE SELECT * FROM ST_Read('traffic_signs.geojson');
-- 2 CRS from GeoParquet metadata
SELECT file_name, json_extract(decode(value), '$.columns.geometry.crs.id') AS crs_id, json_extract(decode(value), '$.columns.geometry.geometry_types') AS geom_types, json_extract(decode(value), '$.columns.geometry.encoding') AS encoding FROM parquet_kv_metadata(['osm_roads.parquet','overture_segments.parquet']) WHERE decode(key) = 'geo';
-- 3 geometry types, empty, null, validity
SELECT count(*) AS signs, count(DISTINCT id) AS unique_ids, count(*) FILTER (WHERE NOT ST_IsValid(geom)) AS invalid, count(*) FILTER (WHERE NOT ST_Intersects(geom, ST_MakeEnvelope(19.80, 49.95, 20.15, 50.15))) AS outside_bbox, min(first_seen_at) AS first_seen_min, max(last_seen_at) AS last_seen_max FROM ST_Read('traffic_signs.geojson');
SELECT count(*) AS photos, count(*) FILTER (WHERE NOT (longitude BETWEEN 19.80 AND 20.15 AND latitude BETWEEN 49.95 AND 50.15)) AS photos_outside_bbox FROM read_csv('photos.csv');
SELECT count(*) FILTER (WHERE NOT ST_Intersects(geometry, ST_MakeEnvelope(19.80, 49.95, 20.15, 50.15))) AS osm_not_touching_bbox, count(*) FILTER (WHERE ST_Length(ST_Transform(geometry, 'EPSG:4326', 'EPSG:2180', always_xy := true)) < 1) AS osm_shorter_than_1m, round(sum(ST_Length(ST_Transform(geometry, 'EPSG:4326', 'EPSG:2180', always_xy := true))) / 1000) AS osm_total_km FROM read_parquet('osm_roads.parquet');
-- 4 duplicates
SELECT 'photos.photo_id' AS k, count(*) - count(DISTINCT photo_id) AS duplicates FROM read_csv('photos.csv') UNION ALL SELECT 'photos.sha256', count(*) - count(DISTINCT sha256) FROM read_csv('photos.csv') UNION ALL SELECT 'photos.filename', count(*) - count(DISTINCT filename) FROM read_csv('photos.csv') UNION ALL SELECT 'links.photo_id', count(*) - count(DISTINCT photo_id) FROM read_csv('photo_road_links.csv') UNION ALL SELECT 'osm geometry (identical WKB)', count(*) - count(DISTINCT ST_AsWKB(geometry)) FROM read_parquet('osm_roads.parquet') UNION ALL SELECT 'signs position (identical point)', count(*) - count(DISTINCT ST_AsText(geom)) FROM ST_Read('traffic_signs.geojson');
-- 5 key relations
SELECT (SELECT count(*) FROM read_csv('photo_road_links.csv') l WHERE l.photo_id NOT IN (SELECT photo_id FROM read_csv('photos.csv'))) AS links_without_photo, (SELECT count(*) FROM read_csv('photos.csv') p WHERE p.photo_id NOT IN (SELECT photo_id FROM read_csv('photo_road_links.csv'))) AS photos_without_link_row, (SELECT count(*) FROM read_csv('photo_road_links.csv') l WHERE l.osm_way_id IS NOT NULL AND l.osm_way_id NOT IN (SELECT osm_id FROM read_parquet('osm_roads.parquet'))) AS links_osm_missing, (SELECT count(*) FROM read_csv('photo_road_links.csv') l WHERE l.overture_id IS NOT NULL AND l.overture_id NOT IN (SELECT id FROM read_parquet('overture_segments.parquet'))) AS links_overture_missing, (SELECT count(DISTINCT osm_way_id) FROM read_csv('photo_road_links.csv')) AS distinct_linked_ways;
SELECT photo_id, osm_way_id, overture_id, match_method, candidate_flags FROM read_csv('photo_road_links.csv') WHERE match_method <> 'osm_source_reference' ORDER BY photo_id;
SELECT split_part(photo_id, '_', 1) AS prefix, source, count(*) FROM read_csv('photos.csv') GROUP BY ALL;
WITH img AS (SELECT DISTINCT unnest(image_ids) AS image_id FROM ST_Read('traffic_signs.geojson')) SELECT count(*) AS mapillary_photos, count(*) FILTER (WHERE replace(photo_id, 'mapillary_', '') IN (SELECT image_id FROM img)) AS referenced_by_a_sign FROM read_csv('photos.csv') WHERE source = 'Mapillary';
-- 6 maxspeed formats
SELECT CASE WHEN maxspeed IS NULL THEN '(null)' WHEN regexp_full_match(maxspeed, '\d+') THEN 'integer' WHEN maxspeed ILIKE '%mph%' THEN 'mph' WHEN maxspeed ILIKE '%km/h%' OR maxspeed ILIKE '%kmh%' THEN 'km/h unit' WHEN maxspeed LIKE '%:%' THEN 'implicit XX:*' WHEN maxspeed IN ('none','signals','walk','variable') THEN 'keyword' WHEN maxspeed LIKE '%;%' OR maxspeed LIKE '%,%' THEN 'multiple values' ELSE 'other' END AS format, count(*) AS n FROM read_parquet('osm_roads.parquet') GROUP BY 1 ORDER BY 2 DESC;
SELECT maxspeed, count(*) AS n FROM read_parquet('osm_roads.parquet') WHERE maxspeed IS NOT NULL GROUP BY 1 ORDER BY 2 DESC, 1;
SELECT k AS tag_key, count(*) AS ways FROM (SELECT unnest(json_keys(tags)) AS k FROM read_parquet('osm_roads.parquet')) WHERE k LIKE '%maxspeed%' GROUP BY 1 ORDER BY 2 DESC;
SELECT 'maxspeed:forward' AS k, json_extract_string(tags, '$."maxspeed:forward"') AS v, count(*) FROM read_parquet('osm_roads.parquet') WHERE v IS NOT NULL GROUP BY ALL UNION ALL SELECT 'maxspeed:backward', json_extract_string(tags, '$."maxspeed:backward"') AS v, count(*) FROM read_parquet('osm_roads.parquet') WHERE v IS NOT NULL GROUP BY ALL UNION ALL SELECT 'maxspeed:variable', json_extract_string(tags, '$."maxspeed:variable"') AS v, count(*) FROM read_parquet('osm_roads.parquet') WHERE v IS NOT NULL GROUP BY ALL ORDER BY 1, 3 DESC;
SELECT json_extract_string(tags, '$."maxspeed:conditional"') AS conditional, highway, count(*) FROM read_parquet('osm_roads.parquet') WHERE conditional IS NOT NULL GROUP BY ALL ORDER BY 3 DESC LIMIT 10;
SELECT 'source:maxspeed' AS k, json_extract_string(tags, '$."source:maxspeed"') AS v, count(*) FROM read_parquet('osm_roads.parquet') WHERE v IS NOT NULL GROUP BY ALL UNION ALL SELECT 'maxspeed:type', json_extract_string(tags, '$."maxspeed:type"') AS v, count(*) FROM read_parquet('osm_roads.parquet') WHERE v IS NOT NULL GROUP BY ALL ORDER BY 1, 3 DESC;
SELECT json_extract_string(tags, '$."source:maxspeed"') AS src, maxspeed, count(*) AS n FROM read_parquet('osm_roads.parquet') WHERE src IN ('PL:urban','PL:rural','PL:zone30','PL:living_street','PL:motorway','PL:expressway') GROUP BY ALL ORDER BY 1, 3 DESC;
SELECT highway, count(*) AS no_limit_at_all FROM read_parquet('osm_roads.parquet') WHERE maxspeed IS NULL AND json_extract_string(tags, '$."maxspeed:forward"') IS NULL AND json_extract_string(tags, '$."maxspeed:backward"') IS NULL AND highway IN ('motorway','trunk','primary','secondary','motorway_link','trunk_link','primary_link','secondary_link') GROUP BY 1 ORDER BY 2 DESC;
-- Overture speed rules
SELECT r.max_speed.unit AS unit, count(*) AS rules, count(*) FILTER (WHERE r."when" IS NOT NULL) AS with_when, count(*) FILTER (WHERE r."between" IS NOT NULL) AS with_between FROM (SELECT unnest(speed_limits) AS r FROM read_parquet('overture_segments.parquet')) GROUP BY 1;
-- signs value distribution
SELECT regexp_extract(object_value, 'limit-(\d+)--', 1) AS value_kmh, count(*) AS signs FROM ST_Read('traffic_signs.geojson') GROUP BY 1 ORDER BY 2 DESC;
SELECT count(*) FILTER (WHERE NOT regexp_full_match(object_value, 'regulatory--maximum-speed-limit-\d+--g\d+')) AS nonmatching_object_value FROM ST_Read('traffic_signs.geojson');
-- 7 missing values per column
SELECT count(*) - count(heading) AS heading_null, count(*) FILTER (WHERE heading = 0) AS heading_zero, count(*) - count(captured_at) AS captured_null, count(*) - count(horizontal_accuracy_m) AS accuracy_null, count(*) - count(sequence) AS sequence_null, count(*) FILTER (WHERE is_panorama) AS panoramas FROM read_csv('photos.csv');
SELECT count(*) - count(osm_way_id) AS osm_null, count(*) - count(overture_id) AS overture_null, count(*) - count(distance_m) AS distance_null, count(*) - count(way_bearing) AS bearing_null, count(*) - count(candidate_flags) AS no_flags FROM read_csv('photo_road_links.csv');
SELECT count(*) - count(name) AS name_null, count(*) - count(oneway) AS oneway_null, count(*) FILTER (WHERE bridge IS NOT NULL AND bridge <> 'no') AS bridges, count(*) FILTER (WHERE tunnel IS NOT NULL AND tunnel <> 'no') AS tunnels, count(*) FILTER (WHERE layer IS NOT NULL AND layer <> '0') AS nonzero_layer FROM read_parquet('osm_roads.parquet');
SELECT 'osm' AS src, split_part(ST_AsText(geometry), ' ', 1) AS gtype, count(*) AS n, count(*) FILTER (WHERE ST_IsEmpty(geometry)) AS empty, count(*) FILTER (WHERE geometry IS NULL) AS null_geom FROM read_parquet('osm_roads.parquet') GROUP BY ALL UNION ALL SELECT 'overture', split_part(ST_AsText(geometry), ' ', 1), count(*), count(*) FILTER (WHERE ST_IsEmpty(geometry)), count(*) FILTER (WHERE geometry IS NULL) FROM read_parquet('overture_segments.parquet') GROUP BY ALL UNION ALL SELECT 'signs', split_part(ST_AsText(geom), ' ', 1), count(*), count(*) FILTER (WHERE ST_IsEmpty(geom)), count(*) FILTER (WHERE geom IS NULL) FROM ST_Read('traffic_signs.geojson') GROUP BY ALL ORDER BY 1;
SELECT flag, count(*) AS n FROM (SELECT trim(unnest(string_split(candidate_flags, ';'))) AS flag FROM read_csv('photo_road_links.csv') WHERE candidate_flags IS NOT NULL) GROUP BY 1 ORDER BY 2 DESC;
SELECT min(captured_at) AS photo_min, max(captured_at) AS photo_max FROM read_csv('photos.csv');
SELECT tunnel, count(*) FROM read_parquet('osm_roads.parquet') WHERE tunnel IS NOT NULL GROUP BY 1 ORDER BY 2 DESC;
SELECT bridge, count(*) FROM read_parquet('osm_roads.parquet') WHERE bridge IS NOT NULL GROUP BY 1 ORDER BY 2 DESC;
SELECT highway, count(*) AS variable_ways, count(maxspeed) AS with_maxspeed FROM read_parquet('osm_roads.parquet') WHERE json_extract_string(tags, '$."maxspeed:variable"') IS NOT NULL GROUP BY 1 ORDER BY 2 DESC;
SELECT count(*) AS directional_ways, count(maxspeed) AS also_plain_maxspeed, count(*) FILTER (WHERE json_extract_string(tags, '$."maxspeed:forward"') IS NOT NULL AND json_extract_string(tags, '$."maxspeed:backward"') IS NULL) AS forward_only, count(*) FILTER (WHERE json_extract_string(tags, '$."maxspeed:backward"') IS NOT NULL AND json_extract_string(tags, '$."maxspeed:forward"') IS NULL) AS backward_only FROM read_parquet('osm_roads.parquet') WHERE json_extract_string(tags, '$."maxspeed:forward"') IS NOT NULL OR json_extract_string(tags, '$."maxspeed:backward"') IS NOT NULL;
SELECT osm_id, highway, maxspeed, json_extract_string(tags, '$."maxspeed:forward"') AS fwd, json_extract_string(tags, '$."maxspeed:backward"') AS bwd FROM read_parquet('osm_roads.parquet') WHERE json_extract_string(tags, '$."maxspeed:forward"') LIKE 'PL:%' OR json_extract_string(tags, '$."maxspeed:backward"') LIKE 'PL:%' ORDER BY osm_id;
SELECT a.id, b.id AS same_position_as, a.object_value, b.object_value AS other_value FROM ST_Read('traffic_signs.geojson') a JOIN ST_Read('traffic_signs.geojson') b ON ST_Equals(a.geom, b.geom) AND a.id < b.id;
SELECT count(*) AS signs_last_seen_before_2025 FROM ST_Read('traffic_signs.geojson') WHERE last_seen_at < TIMESTAMPTZ '2025-01-01';
SELECT count(*) FILTER (WHERE ov_unit IS NULL) AS no_rule, count(*) AS segments FROM (SELECT id, speed_limits[1].max_speed.unit AS ov_unit FROM read_parquet('overture_segments.parquet'));
SELECT count(*) AS offline_files_listed FROM read_csv('offline/ATTRIBUTION.csv');
